export const code = async (inputs) => {
  const str = (v) => String(v === undefined || v === null ? '' : v);
  const bool = (v) => v === true || str(v).toLowerCase() === 'true';
  const hmac = (inputs.hmac && typeof inputs.hmac === 'object') ? inputs.hmac : {};
  return {
    valid: hmac.valid === true || str(hmac.valid) === 'true',
    telegramId: str(hmac.telegramId),
    action: str(inputs.action).trim().toLowerCase(),
    eventId: str(inputs.eventId).trim(),
    consentPdn: bool(inputs.consentPdn),
    consentMarketing: bool(inputs.consentMarketing),
    profileFirst: str(inputs.profileFirst).trim(),
    profileLast: str(inputs.profileLast).trim(),
    profilePosition: str(inputs.profilePosition).trim(),
    profileCompany: str(inputs.profileCompany).trim(),
    profileCity: str(inputs.profileCity).trim(),
    now: new Date().toISOString()
  };
};

export const code = async (inputs) => {
  const texts = (inputs.texts && typeof inputs.texts === 'object') ? inputs.texts : {};
  const t = (key, vars) => {
    let s = String(texts[key] === undefined || texts[key] === null ? key : texts[key]);
    if (vars) Object.keys(vars).forEach((k) => { s = s.split('{' + k + '}').join(String(vars[k])); });
    return s;
  };
  const str = (v) => String(v === undefined || v === null ? '' : v);
  const arr = (src) => Array.isArray(src) ? src : (src && Array.isArray(src.records) ? src.records : []);
  const flat = (rec) => {
    const out = {};
    const cells = (rec && rec.cells) || {};
    Object.keys(cells).forEach((fid) => {
      const c = cells[fid];
      if (c && typeof c === 'object' && typeof c.fieldName === 'string') out[c.fieldName] = c.value === undefined || c.value === null ? '' : String(c.value);
    });
    return out;
  };
  const parseIso = (s) => Date.parse(/[Zz]$/.test(s) || /[+-][0-9]{2}:?[0-9]{2}$/.test(s) ? s : s + 'Z');
  const dateFmt = new Intl.DateTimeFormat('ru-RU', { timeZone: 'Asia/Tashkent', day: 'numeric', month: 'long', hour: '2-digit', minute: '2-digit', hourCycle: 'h23' });
  const fmt = (iso) => {
    const ms = parseIso(iso);
    return isFinite(ms) ? dateFmt.format(new Date(ms)) : '';
  };

  const telegramId = str(inputs.telegramId);
  const action = str(inputs.action);
  const eventId = str(inputs.eventId);
  const consentPdn = inputs.consentPdn === true || str(inputs.consentPdn) === 'true';
  const consentMarketing = inputs.consentMarketing === true || str(inputs.consentMarketing) === 'true';
  const now = str(inputs.now);
  const reqProfile = {
    first: str(inputs.profileFirst).trim(),
    last: str(inputs.profileLast).trim(),
    position: str(inputs.profilePosition).trim(),
    company: str(inputs.profileCompany).trim(),
    city: str(inputs.profileCity).trim()
  };
  const validProfile = (o) => {
    if (o.first.length < 2 || o.last.length < 2) return false;
    if ((o.first + ' ' + o.last).length > 80) return false;
    if (o.position === '' || o.position.length > 200) return false;
    if (o.city === '' || o.city.length > 100) return false;
    return true;
  };

  // Постфильтры повторяют фильтры шагов — defense in depth (Q25).
  const myRegs = arr(inputs.myRegs).map(flat).filter((r) => str(r.telegram_id) === telegramId);
  const eventRegs = arr(inputs.eventRegs).map(flat).filter((r) => str(r.event_id) === eventId);
  const ev = arr(inputs.eventRecords).map(flat).find((r) => str(r.id) === eventId);
  const userRow = arr(inputs.userRows).map(flat).find((r) => str(r.telegram_id) === telegramId) || {};
  const profileDone = str(userRow.profile_completed_at) !== '';
  const storedProfile = {
    first: str(userRow.profile_first_name),
    last: str(userRow.profile_last_name),
    position: str(userRow.position),
    company: str(userRow.company),
    city: str(userRow.city)
  };
  const title = ev ? str(ev.title) : '';

  const base = { ok: false, outcome: '', error: '', reason: '', text: '', eventId: eventId, mine: [], regId: '', consentValue: 'false', profile: {}, httpStatus: 200 };

  if (action === 'mine') {
    // «Мои билеты»: только регистрации вызывающего, только живые (W43, PAR-4).
    const mine = myRegs
      .filter((r) => str(r.status) === 'registered' || str(r.status) === 'checked_in')
      .map((r) => ({
        eventId: str(r.event_id),
        status: str(r.status),
        registeredAt: str(r.registered_at),
        checkedInAt: str(r.checked_in_at)
      }));
    return Object.assign(base, { httpStatus: 200, ok: true, outcome: 'mine', mine: mine });
  }

  if (action === 'profile_get') {
    // W50 / PAR-8: таб «Профиль» — поля и отметка согласия (согласие залочено).
    return Object.assign(base, {
      httpStatus: 200, ok: true, outcome: 'profile', profile: storedProfile,
      pdnDone: t('profile.pdn_done', { when: str(userRow.consent_pdn_at) })
    });
  }

  if (action === 'profile_save') {
    // W50 / PAR-8: правка профиля табом; валидация та же, что в шите.
    if (!validProfile(reqProfile)) {
      return Object.assign(base, { httpStatus: 400, error: 'validation', text: t('profile.err') });
    }
    return Object.assign(base, { httpStatus: 200, ok: true, outcome: 'profile_saved', profile: reqProfile });
  }

  if (action === 'register') {
    if (!consentPdn) {
      return Object.assign(base, { httpStatus: 400, error: 'pdn_required', text: t('reg.err.pdn_required') });
    }
    // W50 / PAR-8: каталог регистрирует только заполненный профиль; первое
    // касание идёт чатом (онбординг), шит профиля в каталоге — срез 6.
    // Профиль из запроса (шит) тоже годится: валиден — пишем вместе с регистрацией.
    let profile = storedProfile;
    let writeProfile = false;
    if (!profileDone) {
      if (!validProfile(reqProfile)) {
        return Object.assign(base, { httpStatus: 400, error: 'profile_required', text: t('reg.err.profile_required') });
      }
      profile = reqProfile;
      writeProfile = true;
    }
    if (eventId === '') {
      return Object.assign(base, { httpStatus: 400, error: 'bad_request', text: t('reg.err.bad_request') });
    }
    const mineRow = eventRegs.find((r) => str(r.telegram_id) === telegramId);
    const mineStatus = mineRow ? str(mineRow.status) : '';
    if (mineStatus === 'registered' || mineStatus === 'checked_in') {
      // IDM-1: повтор — та же регистрация, второго подтверждения нет.
      return Object.assign(base, { httpStatus: 200, ok: true, outcome: 'existing', text: t('reg.already', { title: title }) });
    }
    if (!ev) {
      return Object.assign(base, { httpStatus: 404, error: 'not_found', reason: 'event_not_found', text: t('common.err.event_not_found') });
    }
    const evStatus = str(ev.status);
    if (evStatus === 'cancelled') {
      return Object.assign(base, { httpStatus: 409, error: 'declined', reason: 'event_cancelled', text: t('reg.event_cancelled') });
    }
    if (evStatus === 'finished') {
      return Object.assign(base, { httpStatus: 409, error: 'declined', reason: 'event_finished', text: t('reg.event_finished') });
    }
    if (evStatus !== 'published') {
      return Object.assign(base, { httpStatus: 409, error: 'declined', reason: 'not_published', text: t('reg.not_published') });
    }
    const deadlineIso = str(ev.reg_deadline_at);
    const deadlineMs = deadlineIso ? parseIso(deadlineIso) : NaN;
    if (isFinite(deadlineMs) && Date.now() > deadlineMs) {
      return Object.assign(base, { httpStatus: 409, error: 'declined', reason: 'deadline_passed', text: t('reg.deadline_passed', { when: fmt(deadlineIso) }) });
    }
    // Лимит мест — capacity × (1 + overbook_pct/100), округление вверх; пустой overbook_pct = 40 (OWN-15).
    const capacityRaw = str(ev.capacity);
    const capacity = capacityRaw === '' ? NaN : Number(capacityRaw);
    const overbookRaw = str(ev.overbook_pct);
    const overbook = (overbookRaw === '' || !isFinite(Number(overbookRaw))) ? 40 : Number(overbookRaw);
    const registeredCount = eventRegs.filter((r) => str(r.status) === 'registered').length;
    if (isFinite(capacity)) {
      const limit = Math.ceil(capacity * (1 + overbook / 100));
      if (registeredCount >= limit) {
        return Object.assign(base, { httpStatus: 409, error: 'declined', reason: 'no_seats', text: t('reg.no_seats') });
      }
    }
    return Object.assign(base, {
      httpStatus: 200, ok: true, outcome: writeProfile ? 'registered_profile' : 'registered',
      text: t('reg.done', { title: title }),
      regId: eventId + '-' + telegramId,
      consentValue: consentMarketing ? 'true' : 'false',
      profile: profile, writeProfile: writeProfile
    });
  }

  if (action === 'cancel') {
    if (eventId === '') {
      return Object.assign(base, { httpStatus: 400, error: 'bad_request', text: t('reg.err.bad_request') });
    }
    const active = eventRegs.find((r) => str(r.telegram_id) === telegramId && str(r.status) === 'registered');
    if (!ev || !active) {
      return Object.assign(base, { httpStatus: 404, error: 'not_found', reason: 'not_registered', text: t('cancel.not_found') });
    }
    // PAR-5: сервер перепроверяет срок — опоздавший запрос получает отказ, а не отмену.
    const startMs = parseIso(str(ev.starts_at));
    if (isFinite(startMs) && Date.now() >= startMs) {
      return Object.assign(base, { httpStatus: 409, error: 'declined', reason: 'too_late', text: t('cancel.too_late') });
    }
    return Object.assign(base, { httpStatus: 200, ok: true, outcome: 'cancelled', text: t('cancel.done', { title: title }) });
  }

  return Object.assign(base, { httpStatus: 400, error: 'bad_request', text: t('reg.err.bad_request') });
};

export const code = async (inputs) => {
  const texts = (inputs.texts && typeof inputs.texts === 'object') ? inputs.texts : {};
  const text = String(texts['reg.err.unauthorized'] || 'reg.err.unauthorized');
  return { httpStatus: 401, ok: false, error: 'invalid_init_data', reason: '', outcome: '', text: text, eventId: '', mine: [] };
};
